import java.util.*; abstract class Cab09{double km;Cab09(double k){km=Math.max(0,k);}abstract double base();boolean nightAllowed(){return true;}double fare(boolean night){double f=Math.max(100,base());return night?f*1.2:f;}} class Mini09 extends Cab09{Mini09(double k){super(k);}double base(){return km*10;}boolean nightAllowed(){return false;}} class Sedan09 extends Cab09{Sedan09(double k){super(k);}double base(){return km*14;}} class SUV09 extends Cab09{SUV09(double k){super(k);}double base(){return km*18;}} public class Week09Problem04{public static void main(String[]z){Scanner s=new Scanner(System.in);int n=s.nextInt();double total=0;for(int i=0;i<n;i++){String t=s.next().toUpperCase();double k=s.nextDouble();boolean night=s.next().equalsIgnoreCase("NIGHT");Cab09 c=t.equals("SEDAN")?new Sedan09(k):t.equals("SUV")?new SUV09(k):new Mini09(k);if(night&&!c.nightAllowed()){System.out.println("Rejected trip");continue;}double f=c.fare(night);System.out.printf("%.2f%n",f);total+=f;}System.out.printf("Total: %.2f%n",total);}}